(async () => {
      try {
        const targetStatus = permissions.validate ? "completed" : "in_progress";
        const [tests, staff, toAct, todayVisits] = await Promise.allSettled([
          fetchCatalog(),
          fetchEmployees(),
          (permissions.enterResult || permissions.validate)
            ? fetchOrders(`?status=${targetStatus}`)
            : Promise.resolve([]),
          // Badge sidebar « Tournées » : nombre de visites à domicile
          // pertinentes pour cet utilisateur (mine si nurse seule, all
          // sinon — le backend décide en fonction du rôle).
          permissions.viewHomeVisits
            ? fetchHomeVisits()
            : Promise.resolve([]),
        ]);
        const len = (s) => s.status === "fulfilled" ? s.value.length : undefined;
        setCounts({
          tests: len(tests),
          staff: len(staff),
          toAct: len(toAct),
          todayVisits: len(todayVisits),
        });
      } catch { /* ignore */ }
    })

(async () => {
      try {
        const inv = await fetchInvoice(apptUuid);
        if (!cancelled) setData(inv);
      } catch (e) {
        if (!cancelled) setErr(e?.detail || "Facture indisponible.");
      } finally { if (!cancelled) setLoading(false); }
    })

(async () => {
      try {
        const data = await fetchCatalog();
        if (!cancelled) setCatalog(data.filter((t) => t.is_active));
      } catch (e) {
        if (!cancelled) setErr(e?.detail || "Catalogue indisponible.");
      } finally { if (!cancelled) setLoadingCatalog(false); }
    })

(async () => {
      try {
        const r = await fetchOrderResult(order.uuid);
        setResult(r);
        setValue(r.value || "");
        setUnit(r.unit || "");
        setRefRange(r.reference_range || "");
        setFlag(r.flag || "normal");
        setComment(r.biologist_comment || "");
      } catch (e) { setErr(e.detail || "Résultat introuvable."); }
      finally { setLoading(false); }
    })

(async () => {
      try {
        const rows = await fetchInventoryMoves(item.uuid);
        if (!cancelled) setHistory(rows);
      } finally { if (!cancelled) setLoadingHist(false); }
    })

